package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec

var discFileLines []string
var discFileIdx int

func formatEdited(val decimal.Decimal, picture string) string {
	// Determine sign - not needed for this program (all positive)
	isNeg := val.IsNegative()
	if isNeg {
		val = val.Neg()
	}
	// split picture
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	var fracDigits int
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
		fracDigits = len(fracPic)
	} else {
		intPic = picture
		fracPic = ""
		fracDigits = 0
	}

	// Prepare value string with fracDigits
	// val should already be truncated/rounded to fracDigits, but ensure
	// we get exactly fracDigits fractional digits by truncating
	// Use Truncate to avoid rounding again, but for formatting MOVE should not round?
	// We will just get integer and fractional parts via string with rounding already done.
	// Using Floor for integer part and fractional remainder.
	scaleVal := val.Truncate(int32(fracDigits))

	// Extract integer and fractional strings
	// Use StringFixed to get exactly fracDigits digits
	s := scaleVal.StringFixed(int32(fracDigits))
	// s like "1234.56" or "0.00" or "1234" when fracDigits==0
	var intStr, fracStr string
	if fracDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
		// handle negative sign already removed
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
	} else {
		intStr = s
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	// Remove sign char if any left
	intStr = strings.TrimPrefix(intStr, "-")
	// Handle integer part "-0" etc
	if intStr == "" {
		intStr = "0"
	}

	// Count placeholders in intPic
	placeholderCount := 0
	// also collect placeholder pic chars in order
	var placeholderPics []byte
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			placeholderCount++
			placeholderPics = append(placeholderPics, c)
		}
	}

	// Overflow: keep low-order digits
	if len(intStr) > placeholderCount {
		intStr = intStr[len(intStr)-placeholderCount:]
	}
	// Pad on left with zeros to placeholderCount
	if len(intStr) < placeholderCount {
		intStr = strings.Repeat("0", placeholderCount-len(intStr)) + intStr
	}
	// padInt is now len placeholderCount
	padInt := intStr

	// Find first non-zero index
	firstNonZero := placeholderCount // meaning all zero
	for i := 0; i < placeholderCount; i++ {
		if padInt[i] != '0' {
			firstNonZero = i
			break
		}
	}

	// Determine which placeholder positions are blank (suppressed)
	isBlank := make([]bool, placeholderCount)
	for i := 0; i < placeholderCount; i++ {
		if padInt[i] == '0' && i < firstNonZero {
			// leading zero
			if placeholderPics[i] == 'Z' {
				isBlank[i] = true
			} else {
				isBlank[i] = false
			}
		} else {
			isBlank[i] = false
		}
	}
	// Special case: all zeros -> we want to keep the last mandatory 9 as 0, which already handled (firstNonZero==placeholderCount, all Z blanks, last 9 not blank)

	// Build integer output
	var intOut strings.Builder
	phIdx := 0
	// For comma handling: comma is blank if all placeholders to its left are blank
	// We can check: if the number of non-blank placeholders emitted so far ==0 and remaining significant not yet seen, commas are spaces.
	// Simpler: comma is space if every placeholder before it is blank.
	// We know isBlank for each placeholder.
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			if isBlank[phIdx] {
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(padInt[phIdx])
			}
			phIdx++
		} else if c == ',' {
			// comma is space if all placeholders before this comma are blank
			// count placeholders before comma: phIdx is number already consumed
			allBlankBefore := true
			for j := 0; j < phIdx; j++ {
				if !isBlank[j] {
					allBlankBefore = false
					break
				}
			}
			if allBlankBefore {
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(',')
			}
		} else {
			intOut.WriteByte(c)
		}
	}

	result := intOut.String()
	if fracDigits > 0 {
		result = result + "." + fracStr
	}
	if isNeg {
		// COBOL would show sign separately; not needed here
		// Place minus in first blank position if possible
		// For simplicity prepend
		result = "-" + result
	}
	return result
}

func formatPIC9(n int64, width int) string {
	s := strconv.FormatInt(n, 10)
	if len(s) > width {
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains only digits (maybe spaces already trimmed)
	// Keep only digits; sign not expected
	neg := false
	if strings.HasPrefix(s, "-") || strings.HasPrefix(s, "+") {
		if s[0] == '-' {
			neg = true
		}
		s = s[1:]
	}
	// Remove non-digits
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	n, _ := strconv.ParseInt(digits, 10, 64)
	// Use decimal.New with exponent -scale
	d := decimal.New(n, -scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func storePIC(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate to scale, then simulate overflow: keep low-order digits
	d = d.Truncate(scale)
	// Overflow handling: mod 10^(intDigits+scale) ??? For 9(5)V99 : intDigits=5 scale2 => max 10^7
	// We can implement by integer representation modulo
	// Convert to integer of smallest unit: d * 10^scale
	mult := decimal.NewFromInt(1)
	for i := int32(0); i < scale; i++ {
		mult = mult.Mul(decimal.NewFromInt(10))
	}
	units := d.Mul(mult).Truncate(0) // integer
	// modulus
	mod := decimal.NewFromInt(1)
	totalDigits := intDigits + int(scale)
	for i := 0; i < totalDigits; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	// Handle negative? Keep sign
	isNeg := units.IsNegative()
	if isNeg {
		units = units.Neg()
	}
	// low-order digits: mod
	// Compute units mod mod
	// decimal mod via Div+Truncate
	if units.GreaterThanOrEqual(mod) || units.GreaterThanOrEqual(decimal.NewFromInt(0).Sub(mod)) {
		// units = units % mod
		// Use integer div
		div := units.Div(mod).Truncate(0)
		units = units.Sub(div.Mul(mod))
	}
	if isNeg {
		units = units.Neg()
	}
	// Back to decimal
	result := units.Div(mult)
	return result
}

func readDiscFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if not exist, treat empty
		discFileLines = []string{}
		return
	}
	content := string(data)
	// Split by lines: COBOL LINE SEQUENTIAL: lines separated by newline (\n or \r\n)
	// Preserve empty trailing line? Use Split
	raw := strings.Split(content, "\n")
	lines := []string{}
	for i, l := range raw {
		// Remove trailing \r
		if strings.HasSuffix(l, "\r") {
			l = strings.TrimSuffix(l, "\r")
		}
		// If last element is empty due to final newline, ignore? COBOL would not have extra record.
		if i == len(raw)-1 && l == "" {
			continue
		}
		lines = append(lines, l)
	}
	discFileLines = lines
	discFileIdx = 0
}

func mainPara() {
	// OPEN INPUT DISC-FILE
	readDiscFile()
	performReadPara()
	for !isInputDone() {
		performProcessPara()
	}
	// CLOSE DISC-FILE (no-op)
	performSummaryPara()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func performReadPara() {
	readPara()
}

func readPara() {
	if discFileIdx >= len(discFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := discFileLines[discFileIdx]
	discFileIdx++
	// Pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// Parse fields
	drItem := line[0:6]
	drPriceStr := line[6:13]
	drPctStr := line[13:15]

	// PIC X(6) exactly 6 chars
	discRec.DrItem = drItem
	discRec.DrPrice = parseDecimalDigits(drPriceStr, 2)
	// PIC 9(2) integer
	trimPct := strings.TrimSpace(drPctStr)
	if trimPct == "" {
		discRec.DrPct = 0
	} else {
		// digits only
		digits := ""
		for _, ch := range drPctStr {
			if ch >= '0' && ch <= '9' {
				digits += string(ch)
			}
		}
		if digits == "" {
			discRec.DrPct = 0
		} else {
			v, _ := strconv.ParseInt(digits, 10, 64)
			discRec.DrPct = v
		}
	}
}

func performProcessPara() {
	processPara()
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	// Use decimal arithmetic: multiply before dividing, round to 2
	tmp := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	// divide by 100 via Shift(-2)
	tmp = tmp.Shift(-2)
	tmp = tmp.Round(2)
	WsDiscount = storePIC(tmp, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	tmp2 := discRec.DrPrice.Sub(WsDiscount)
	tmp2 = truncateDecimal(tmp2, 2)
	WsNet = storePIC(tmp2, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = WsTotalNet.Add(WsNet)
	WsTotalNet = truncateDecimal(WsTotalNet, 2)
	WsTotalNet = storePIC(WsTotalNet, 8, 2)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// overflow truncate to 3 digits
	if WsCount > 999 {
		WsCount = WsCount % 1000
	}

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-ITEM is X(6) exactly 6 chars (including spaces)
	// DR-PCT is unedited PIC 9(2) zero-padded
	pctStr := formatPIC9(discRec.DrPct, 2)
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Println(line)

	performReadPara()
}

func performSummaryPara() {
	summaryPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatPIC9(WsCount, 3)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Println(line)
}

func main() {
	// Initialize package-level vars already set
	// Ensure stdout exactly as COBOL DISPLAY
	// Use buffered writer? fmt.Println is fine
	// Run
	_ = bufio.NewReader(nil) // keep import
	mainPara()
}
